CREATE    VIEW [synapse_fo].[vwECORESCATEGORYSYSTEMLANGUAGE]
AS
SELECT T1.RECID AS CATEGORY
	,T1.PARTITION AS PARTITION
	,T1.RECID AS RECID
	,T2.SYSTEMLANGUAGEID AS SYSTEMLANGUAGEID
	,T2.PARTITION AS PARTITION#2
FROM synapse_fo.ECORESCATEGORY T1
CROSS JOIN synapse_fo.SYSTEMPARAMETERS T2
WHERE (
		--(T2.KEY_ = 0)
		--AND 
		(T1.PARTITION = T2.PARTITION)
		)
